func main() {
 tests := []struct {
  dirPath   string
  filename  string
  expected  string
}{
  {"/var/www", "config.json", "/var/www/config.json"},
  {"/var/www", "../config.json", "/var/www/config.json"},
  {"/var/www", "../../etc/passwd", "/var/www/etc/passwd"},
 }

 for _, test := range tests {
  filePath := fmt.Sprintf("%s/%s", test.dirPath, test.filename)
  cleanedPath := filepath.Clean(filePath)
  fmt.Printf("Test case: dirPath=%q, filename=%q\n", test.dirPath, test.filename)
  fmt.Printf("  filePath: %q => cleanedPath: %q\n", filePath, cleanedPath)
  if cleanedPath != test.expected {
   panic(fmt.Sprintf("Expected cleaned path to be %q but got %q", test.expected, cleanedPath))
  }
 }
}

